// QA adapter for trusted files generated by this experiment only.
// Not a general-purpose or malformed-input parser; do not feed untrusted files.
#include "realityforge/mesh_topology.hpp"
#include <iostream>
#include <fstream>
int main(int argc,char**argv){if(argc!=2)return 2;std::ifstream in(argv[1]);std::size_t nv,nt;in>>nv>>nt;rf::SurfaceMesh m;m.vertices.resize(nv);m.triangles.resize(nt);for(auto&v:m.vertices)in>>v.xyz.x>>v.xyz.y>>v.xyz.z;for(auto&t:m.triangles)in>>t.a>>t.b>>t.c;if(!in)return 3;const auto r=rf::analyzeMeshTopology(m);std::cout<<"{\"nonmanifoldEdges\":"<<r.nonmanifoldEdges<<",\"degenerateFaces\":"<<r.degenerateFaces.size()<<",\"duplicateFaces\":"<<r.duplicateFaces.size()<<",\"windingConflicts\":"<<r.windingConflictFaces.size()<<",\"nonmanifoldVertices\":"<<r.nonmanifoldVertices<<",\"intersections\":"<<r.intersections.size()<<",\"incomplete\":"<<(r.intersectionBudgetExceeded?"true":"false")<<",\"boundaryEdges\":"<<r.boundaryEdges<<",\"components\":"<<r.components<<"}\n";}
